 61→  }>({ visible: false, x: 0, y: 0, entry: null });
 62→
 63→  // Load bin on mount
 64→  useEffect(() => {
 65→    void loadBin();
 66→  }, [loadBin]);
 67→
 68→  // Prune stale selectedIds when entries change
 69→  const entryIds = useMemo(() => new Set(entries.map((e) => e.id)), [entries]);
 70→  useEffect(() => {
 71→    setSelectedIds((prev) => {
 72→      if (prev.size === 0) return prev;
 73→      const pruned = new Set([...prev].filter((id) => entryIds.has(id)));
 74→      if (pruned.size === prev.size) return prev;
 75→      return pruned;
 76→    });
 77→  }, [entryIds]);
 78→
 79→  // Sort entries
 80→  const sortedEntries = useMemo(() => {
 81→    const sorted = [...entries].sort((a, b) => {
 82→      let cmp = 0;
 83→      switch (sortField) {
 84→        case 'name':
 85→          cmp = a.name.localeCompare(b.name, undefined, { sensitivity: 'base' });
 86→          break;
 87→        case 'deletedAt':
 88→          cmp = a.deletedAt - b.deletedAt;
 89→          break;
 90→        case 'size':
 91→          cmp = a.size - b.size;
 92→          break;
 93→        case 'daysRemaining':
 94→          cmp = daysRemaining(a) - daysRemaining(b);
 95→          break;
 96→      }
 97→      return sortDirection === 'asc' ? cmp : -cmp;
 98→    });
 99→    return sorted;
100→  }, [entries, sortField, sortDirection, daysRemaining]);
101→
102→  // Toggle sort column
103→  const handleSortClick = useCallback(
104→    (field: SortField) => {
105→      if (sortField === field) {
106→        setSortDirection((prev) => (prev === 'asc' ? 'desc' : 'asc'));
107→      } else {
108→        setSortField(field);
109→        setSortDirection(field === 'name' ? 'asc' : 'desc');
110→      }
111→    },
112→    [sortField]
113→  );
114→
115→  // Sort indicator
116→  const sortIndicator = (field: SortField) => {
117→    if (sortField !== field) return '';
118→    return sortDirection === 'asc' ? ' ^' : ' v';
119→  };
120→
121→  // Selection handlers
122→  const handleSelect = useCallback(
123→    (entryId: string, event: { ctrlKey: boolean; shiftKey: boolean; metaKey: boolean }) => {
124→      const isCtrl = event.ctrlKey || event.metaKey;
125→      const isShift = event.shiftKey;
126→
127→      if (isShift && lastSelectedIdRef.current) {
128→        const ids = sortedEntries.map((e) => e.id);
129→        const startIdx = ids.indexOf(lastSelectedIdRef.current);
130→        const endIdx = ids.indexOf(entryId);
131→        if (startIdx !== -1 && endIdx !== -1) {
132→          const rangeStart = Math.min(startIdx, endIdx);
133→          const rangeEnd = Math.max(startIdx, endIdx);
134→          const rangeIds = ids.slice(rangeStart, rangeEnd + 1);
135→          setSelectedIds((prev) => {
136→            const next = new Set(prev);
137→            for (const id of rangeIds) next.add(id);
138→            return next;
139→          });
140→          lastSelectedIdRef.current = entryId;
141→        } else {
142→          // Stale anchor — fall back to selecting the clicked row
143→          setSelectedIds(new Set([entryId]));
144→          lastSelectedIdRef.current = entryId;
145→        }
146→      } else if (isCtrl) {
147→        setSelectedIds((prev) => {
148→          const next = new Set(prev);
149→          if (next.has(entryId)) next.delete(entryId);
150→          else next.add(entryId);
151→          return next;
152→        });
153→        lastSelectedIdRef.current = entryId;
154→      } else {
155→        setSelectedIds(new Set([entryId]));
156→        lastSelectedIdRef.current = entryId;
157→      }
158→    },
159→    [sortedEntries]
160→  );
161→
162→  const clearSelection = useCallback(() => {
