2606→+/**
2607→+ * Bin Service - Recycle bin metadata IPNS lifecycle
2608→+ *
2609→+ * Manages the encrypted bin metadata: initialize on login, add entries on delete,
2610→+ * restore items, permanent delete (with CID unpin + quota update), empty bin,
2611→+ * and auto-purge expired entries.
2612→+ *
2613→+ * Follows the same IPFS/IPNS patterns as device-registry.service.ts.
2614→+ *
2615→+ * IMPORTANT: Bin operations must NEVER block login or the delete UI.
2616→+ * initializeBin is fire-and-forget; addToBin is fire-and-forget from the
2617→+ * delete flow. Errors are caught and logged, not thrown to callers.
2618→+ */
2619→+
2620→+import {
2621→+  deriveBinIpnsKeypair,
2622→+  encryptBinMetadata,
2623→+  decryptBinMetadata,
2624→+  bytesToHex,
2625→+  hexToBytes,
2626→+  wrapKey,
2627→+  type RecycleBinMetadata,
2628→+  type BinEntry,
2629→+  type FolderChild,
2630→+  type FilePointer,
2631→+  type FolderEntry,
2632→+} from '@cipherbox/crypto';
2633→+import { addToIpfs, fetchFromIpfs, unpinFromIpfs } from '../lib/api/ipfs';
2634→+import { createAndPublishIpnsRecord, resolveIpnsRecord } from './ipns.service';
2635→+import { useAuthStore } from '../stores/auth.store';
2636→+import { useBinStore } from '../stores/bin.store';
2637→+import { useFolderStore } from '../stores/folder.store';
2638→+import { useVaultStore } from '../stores/vault.store';
2639→+import { useQuotaStore } from '../stores/quota.store';
2640→+import type { FolderNode } from '../stores/folder.store';
2641→+
2642→+// Track whether TEE enrollment has been done for this session
2643→+let binTeeEnrolled = false;
2644→+
2645→+// ---------------------------------------------------------------------------
2646→+// Internal helpers: load / save bin metadata
2647→+// ---------------------------------------------------------------------------
2648→+
2649→+/**
2650→+ * Load and decrypt bin metadata from IPNS.
2651→+ *
2652→+ * @returns Decrypted metadata and IPNS resolution data, or null if no bin exists yet
2653→+ */
2654→+async function loadBinMetadata(params: { userPrivateKey: Uint8Array }): Promise<{
2655→+  metadata: RecycleBinMetadata;
2656→+  ipnsName: string;
2657→+  sequenceNumber: bigint;
2658→+} | null> {
2659→+  const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
2660→+  const resolved = await resolveIpnsRecord(binIpns.ipnsName);
2661→+
2662→+  if (!resolved) {
2663→+    return null;
2664→+  }
2665→+
2666→+  const encryptedBytes = await fetchFromIpfs(resolved.cid);
2667→+  const metadata = await decryptBinMetadata(encryptedBytes, params.userPrivateKey);
2668→+
2669→+  return {
2670→+    metadata,
2671→+    ipnsName: binIpns.ipnsName,
2672→+    sequenceNumber: resolved.sequenceNumber,
2673→+  };
2674→+}
2675→+
2676→+/**
2677→+ * Encrypt and publish bin metadata to IPNS.
2678→+ *
2679→+ * Handles TEE enrollment on first write.
2680→+ */
2681→+async function saveBinMetadata(params: {
2682→+  metadata: RecycleBinMetadata;
2683→+  userPublicKey: Uint8Array;
2684→+  userPrivateKey: Uint8Array;
2685→+}): Promise<void> {
2686→+  const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
2687→+
2688→+  // Encrypt metadata with user's public key (ECIES)
2689→+  const encryptedBytes = await encryptBinMetadata(params.metadata, params.userPublicKey);
2690→+
2691→+  // Pin to IPFS
2692→+  const { cid } = await addToIpfs(new Blob([encryptedBytes as BlobPart]));
2693→+
2694→+  // TEE enrollment on first write (fire-and-forget)
2695→+  let encryptedIpnsKey: string | undefined;
2696→+  let keyEpoch: number | undefined;
2697→+
2698→+  if (!binTeeEnrolled) {
2699→+    const teeKeys = useAuthStore.getState().teeKeys;
2700→+    if (teeKeys?.currentPublicKey) {
2701→+      try {
2702→+        const wrappedKey = await wrapKey(binIpns.privateKey, hexToBytes(teeKeys.currentPublicKey));
2703→+        encryptedIpnsKey = bytesToHex(wrappedKey);
2704→+        keyEpoch = teeKeys.currentEpoch;
2705→+        binTeeEnrolled = true;
2706→+      } catch (err) {
2707→+        console.error('[Bin] TEE enrollment failed (non-blocking):', err);
2708→+      }
2709→+    }
2710→+  }
2711→+
2712→+  // Publish IPNS record
2713→+  await createAndPublishIpnsRecord({
2714→+    ipnsPrivateKey: binIpns.privateKey,
2715→+    ipnsName: binIpns.ipnsName,
2716→+    metadataCid: cid,
2717→+    sequenceNumber: BigInt(params.metadata.sequenceNumber),
2718→+    encryptedIpnsPrivateKey: encryptedIpnsKey,
2719→+    keyEpoch,
2720→+  });
