426→                nlink: 2,
427→            };
428→            let fuse_attr = attr.to_fuse_attr(current_uid(), current_gid());
429→
430→            let inode = InodeData {
431→                ino,
432→                parent_ino: parent,
433→                name: name_str.to_string(),
434→                kind: InodeKind::Folder {
435→                    ipns_name: ipns_name.clone(),
436→                    encrypted_folder_key: encrypted_folder_key_hex,
437→                    folder_key: zeroize::Zeroizing::new(folder_key.to_vec()),
438→                    ipns_private_key: Some(zeroize::Zeroizing::new(ipns_private_key.clone())),
439→                    children_loaded: true,
440→                },
441→                attr,
442→                children: Some(vec![]),
443→                write_generation: 0,
444→            };
445→
446→            fs.inodes.insert(inode);
447→
448→            if let Some(parent_inode) = fs.inodes.get_mut(parent) {
449→                if let Some(ref mut children) = parent_inode.children {
450→                    children.push(ino);
451→                }
452→                parent_inode.attr.mtime = SystemTime::now();
453→                parent_inode.attr.ctime = SystemTime::now();
454→            }
455→
456→            let metadata = crate::crypto::folder::FolderMetadata {
457→                version: "v2".to_string(),
458→                children: vec![],
459→            };
460→
461→            let json_bytes = crate::fuse::encrypt_metadata_to_json(
462→                &metadata, &folder_key,
463→            )?;
464→
465→            let encrypted_ipns_for_tee = if let Some(ref tee_key) = fs.tee_public_key {
466→                let wrapped = crate::crypto::ecies::wrap_key(&ipns_private_key, tee_key)
467→                    .map_err(|e| format!("TEE key wrapping failed: {}", e))?;
468→                Some(hex::encode(&wrapped))
469→            } else {
470→                None
471→            };
472→            let tee_key_epoch = fs.tee_key_epoch;
473→
474→            let (parent_metadata, parent_folder_key, parent_ipns_key, parent_ipns_name, parent_old_cid) =
475→                fs.build_folder_metadata(parent)?;
476→
477→            let api = fs.api.clone();
478→            let rt = fs.rt.clone();
479→            let ipns_name_clone = ipns_name.clone();
480→            let coordinator = fs.publish_coordinator.clone();
481→
482→            std::thread::spawn(move || {
483→                let result = rt.block_on(async {
484→                    let initial_cid = crate::api::ipfs::upload_content(
485→                        &api, &json_bytes,
486→                    ).await?;
487→
488→                    let ipns_key_arr: [u8; 32] = ipns_private_key.try_into()
489→                        .map_err(|_| "Invalid IPNS key length".to_string())?;
490→                    let value = format!("/ipfs/{}", initial_cid);
491→                    let record = crate::crypto::ipns::create_ipns_record(
492→                        &ipns_key_arr, &value, 0, 86_400_000,
493→                    ).map_err(|e| format!("IPNS record creation failed: {}", e))?;
494→                    let marshaled = crate::crypto::ipns::marshal_ipns_record(&record)
495→                        .map_err(|e| format!("IPNS marshal failed: {}", e))?;
496→
497→                    use base64::Engine;
498→                    let record_b64 = base64::engine::general_purpose::STANDARD
499→                        .encode(&marshaled);
500→
501→                    // New folder initial publish: sequence 0, no conflict check needed
502→                    let req = crate::api::ipns::IpnsPublishRequest {
503→                        ipns_name: ipns_name_clone.clone(),
504→                        record: record_b64,
505→                        metadata_cid: initial_cid,
506→                        encrypted_ipns_private_key: encrypted_ipns_for_tee,
507→                        key_epoch: tee_key_epoch,
508→                        expected_sequence_number: None,
509→                    };
510→                    match crate::api::ipns::publish_ipns(&api, &req).await? {
511→                        crate::api::ipns::PublishResult::Success => {
512→                            coordinator.record_publish(&ipns_name_clone, 0);
513→                            log::info!("New folder IPNS published: {}", ipns_name_clone);
514→                        }
515→                        crate::api::ipns::PublishResult::Conflict { .. } => {
516→                            // Sequence 0 should never conflict -- log and continue
517→                            log::warn!("Unexpected conflict on new folder IPNS publish for {}", ipns_name_clone);
518→                        }
519→                    }
520→
521→                    let lock = coordinator.get_lock(&parent_ipns_name);
522→                    let _guard = lock.lock().await;
523→
524→                    let parent_json = crate::fuse::encrypt_metadata_to_json(
525→                        &parent_metadata, &parent_folder_key,
526→                    )?;
527→
528→                    let seq = coordinator.resolve_sequence(&api, &parent_ipns_name).await?;
529→
530→                    let parent_meta_cid = crate::api::ipfs::upload_content(
531→                        &api, &parent_json,
532→                    ).await?;
533→
534→                    let parent_key_arr: [u8; 32] = parent_ipns_key.try_into()
535→                        .map_err(|_| "Invalid parent IPNS key length".to_string())?;
536→                    let new_seq = seq + 1;
537→                    let parent_value = format!("/ipfs/{}", parent_meta_cid);
538→                    let parent_record = crate::crypto::ipns::create_ipns_record(
539→                        &parent_key_arr, &parent_value, new_seq, 86_400_000,
540→                    ).map_err(|e| format!("Parent IPNS record failed: {}", e))?;
541→                    let parent_marshaled = crate::crypto::ipns::marshal_ipns_record(
542→                        &parent_record,
543→                    ).map_err(|e| format!("Parent IPNS marshal failed: {}", e))?;
544→                    let parent_record_b64 = base64::engine::general_purpose::STANDARD
545→                        .encode(&parent_marshaled);
546→
547→                    // Parent folder publish after mkdir includes conflict detection.
548→                    // On conflict, log a warning -- the debounced publish queue will
549→                    // retry the parent metadata on the next cycle.
550→                    // TODO: Add full re-fetch+merge+retry for parent mkdir publish (v2).
551→                    let parent_req = crate::api::ipns::IpnsPublishRequest {
552→                        ipns_name: parent_ipns_name.clone(),
553→                        record: parent_record_b64,
554→                        metadata_cid: parent_meta_cid,
555→                        encrypted_ipns_private_key: None,
556→                        key_epoch: None,
557→                        expected_sequence_number: Some(seq.to_string()),
558→                    };
559→                    match crate::api::ipns::publish_ipns(&api, &parent_req).await? {
560→                        crate::api::ipns::PublishResult::Success => {
561→                            coordinator.record_publish(&parent_ipns_name, new_seq);
562→                            // Only unpin old CID on successful publish
563→                            if let Some(old) = parent_old_cid {
564→                                let _ = crate::api::ipfs::unpin_content(&api, &old).await;
565→                            }
566→                            log::info!("Parent metadata published after mkdir");
567→                        }
568→                        crate::api::ipns::PublishResult::Conflict { current_sequence_number } => {
569→                            log::warn!(
570→                                "Conflict on parent publish after mkdir (expected seq {}, server has {}). \
571→                                Debounced publish will retry.",
572→                                seq, current_sequence_number
573→                            );
574→                            // Do not record_publish or unpin -- let the next debounced publish pick up fresh seq
575→                        }
576→                    }
577→                    Ok::<(), String>(())
578→                });
579→
580→                if let Err(e) = result {
581→                    log::error!("Background mkdir publish failed: {}", e);
582→                }
583→            });
584→
585→            Ok(fuse_attr)
586→        })();
587→
588→        match result {
589→            Ok(fuse_attr) => {
590→                reply.entry(&DIR_TTL, &fuse_attr, 0);
591→            }
592→            Err(e) => {
593→                log::error!("mkdir failed: {}", e);
594→                reply.error(libc::EIO);
595→            }
596→        }
597→    }
