740→    /// Rename or move a file/folder.
741→    pub fn handle_rename(
742→        fs: &mut CipherBoxFS,
743→        parent: u64,
744→        name: &OsStr,
745→        newparent: u64,
746→        newname: &OsStr,
747→        reply: ReplyEmpty,
748→    ) {
749→        log::debug!(
750→            "rename: {:?} (parent {}) -> {:?} (parent {})",
751→            name, parent, newname, newparent,
752→        );
753→        let name_str = match name.to_str() {
754→            Some(n) => n,
755→            None => {
756→                reply.error(libc::EINVAL);
757→                return;
758→            }
759→        };
760→        let newname_str = match newname.to_str() {
761→            Some(n) => n,
762→            None => {
763→                reply.error(libc::EINVAL);
764→                return;
765→            }
766→        };
767→
768→        // Find source inode (with FUSE-T truncated name fallback)
769→        let (source_ino, actual_name) = match fs.inodes.find_child(parent, name_str) {
770→            Some(ino) => (ino, name_str.to_string()),
771→            None => {
772→                let parent_inode = match fs.inodes.get(parent) {
773→                    Some(i) => i,
774→                    None => {
775→                        reply.error(libc::ENOENT);
776→                        return;
777→                    }
778→                };
779→                let children = parent_inode.children.clone().unwrap_or_default();
780→                let mut matches: Vec<(u64, String)> = Vec::new();
781→                for &child_ino in &children {
782→                    if let Some(child) = fs.inodes.get(child_ino) {
783→                        if is_platform_special(&child.name) {
784→                            continue;
785→                        }
786→                        if child.name.ends_with(name_str) && child.name.len() > name_str.len() {
787→                            matches.push((child_ino, child.name.clone()));
788→                        }
789→                    }
790→                }
791→                if matches.len() == 1 {
792→                    log::debug!(
793→                        "rename suffix-match: truncated {:?} matched full name {:?}",
794→                        name_str, matches[0].1
795→                    );
796→                    (matches[0].0, matches[0].1.clone())
797→                } else {
798→                    log::debug!(
799→                        "rename failed: {:?} not found (suffix matches: {})",
800→                        name_str, matches.len()
801→                    );
802→                    reply.error(libc::ENOENT);
803→                    return;
804→                }
805→            }
806→        };
807→
808→        let name_str = &actual_name;
809→
810→        log::debug!(
811→            "rename: {} (ino {}) in parent {} -> {} in parent {}",
812→            name_str, source_ino, parent, newname_str, newparent,
813→        );
814→
815→        // If destination exists, handle replacement
816→        if let Some(dest_ino) = fs.inodes.find_child(newparent, newname_str) {
817→            // Self-replace (rename "a" to "a" in same dir): no-op
818→            if dest_ino == source_ino {
819→                reply.ok();
820→                return;
821→            }
822→
823→            if let Some(dest_inode) = fs.inodes.get(dest_ino) {
824→                // Validate kind compatibility (POSIX: can't replace file with dir or vice versa)
825→                let source_is_dir = fs.inodes.get(source_ino)
826→                    .map(|i| matches!(i.kind, InodeKind::Root { .. } | InodeKind::Folder { .. }))
827→                    .unwrap_or(false);
828→                let dest_is_dir = matches!(
829→                    dest_inode.kind,
830→                    InodeKind::Root { .. } | InodeKind::Folder { .. }
831→                );
832→                if source_is_dir && !dest_is_dir {
833→                    reply.error(libc::ENOTDIR);
834→                    return;
835→                }
836→                if !source_is_dir && dest_is_dir {
837→                    reply.error(libc::EISDIR);
838→                    return;
839→                }
840→
841→                match &dest_inode.kind {
842→                    InodeKind::Folder { .. } => {
843→                        if let Some(ref children) = dest_inode.children {
844→                            if !children.is_empty() {
845→                                reply.error(libc::ENOTEMPTY);
846→                                return;
847→                            }
848→                        }
849→                    }
850→                    InodeKind::File { cid, .. } => {
851→                        if !cid.is_empty() {
852→                            let cid_clone = cid.clone();
853→                            let api = fs.api.clone();
854→                            fs.rt.spawn(async move {
855→                                let _ = crate::api::ipfs::unpin_content(
856→                                    &api, &cid_clone,
857→                                ).await;
858→                            });
859→                        }
860→                    }
861→                    _ => {}
862→                }
863→            }
864→            fs.inodes.remove(dest_ino);
865→        }
866→
867→        // Remove source from old parent's name index (NFC-normalized)
868→        {
869→            use unicode_normalization::UnicodeNormalization;
870→            let nfc_key: String = name_str.nfc().collect();
871→            fs.inodes.name_to_ino.remove(&(parent, nfc_key));
872→        }
873→
874→        // Update the source inode's name and parent
875→        if let Some(inode) = fs.inodes.get_mut(source_ino) {
876→            inode.name = newname_str.to_string();
877→            inode.parent_ino = newparent;
878→            inode.attr.ctime = SystemTime::now();
879→        }
880→
881→        // Update the name lookup index for the new location (NFC-normalized)
882→        {
883→            use unicode_normalization::UnicodeNormalization;
884→            let nfc_key: String = newname_str.nfc().collect();
885→            fs.inodes.name_to_ino.insert(
886→                (newparent, nfc_key),
887→                source_ino,
888→            );
889→        }
890→
891→        if parent != newparent {
892→            if let Some(old_parent) = fs.inodes.get_mut(parent) {
893→                if let Some(ref mut children) = old_parent.children {
894→                    children.retain(|&c| c != source_ino);
895→                }
896→                old_parent.attr.mtime = SystemTime::now();
897→                old_parent.attr.ctime = SystemTime::now();
898→            }
899→            if let Some(new_parent) = fs.inodes.get_mut(newparent) {
900→                if let Some(ref mut children) = new_parent.children {
901→                    children.push(source_ino);
902→                }
903→                new_parent.attr.mtime = SystemTime::now();
904→                new_parent.attr.ctime = SystemTime::now();
905→            }
906→
907→            if let Err(e) = fs.update_folder_metadata(parent) {
908→                log::error!("Failed to update old parent metadata after rename: {}", e);
909→            }
910→            if let Err(e) = fs.update_folder_metadata(newparent) {
911→                log::error!("Failed to update new parent metadata after rename: {}", e);
912→            }
913→        } else {
914→            if let Some(parent_inode) = fs.inodes.get_mut(parent) {
915→                parent_inode.attr.mtime = SystemTime::now();
916→                parent_inode.attr.ctime = SystemTime::now();
917→            }
918→            if let Err(e) = fs.update_folder_metadata(parent) {
919→                log::error!("Failed to update parent metadata after rename: {}", e);
920→            }
921→        }
922→
923→        reply.ok();
924→    }
