803→+/// Add a BinEntry to the user's encrypted recycle bin IPNS record.
804→+///
805→+/// Background operation: reads existing bin metadata from IPNS (or creates empty),
806→+/// appends the new entry, encrypts with ECIES, uploads to IPFS, publishes IPNS.
807→+/// Fire-and-forget -- errors are logged but don't propagate.
808→+/// CIDs remain pinned on delete for recovery via the web app bin UI.
809→+#[cfg(any(feature = "fuse", feature = "winfsp"))]
810→+pub(crate) fn spawn_bin_entry_publish(
811→+    api: Arc<ApiClient>,
812→+    rt: tokio::runtime::Handle,
813→+    entry: crate::crypto::bin::BinEntry,
814→+    user_private_key: Vec<u8>,
815→+    user_public_key: Vec<u8>,
816→+    coordinator: Arc<PublishCoordinator>,
817→+) {
818→+    std::thread::spawn(move || {
819→+        let result = rt.block_on(async {
820→+            // 1. Derive the bin IPNS keypair from user's private key
821→+            let pk_arr: [u8; 32] = user_private_key.as_slice().try_into()
822→+                .map_err(|_| "Invalid private key length for bin derivation".to_string())?;
823→+            let (bin_ipns_private_key, _bin_ipns_public_key, bin_ipns_name) =
824→+                crate::crypto::hkdf::derive_bin_ipns_keypair(&pk_arr)
825→+                    .map_err(|e| format!("Bin IPNS derivation failed: {}", e))?;
826→+
827→+            // 2. Acquire per-IPNS publish lock
828→+            let lock = coordinator.get_lock(&bin_ipns_name);
829→+            let _guard = lock.lock().await;
830→+
831→+            // 3. Try to resolve existing bin metadata from IPNS
832→+            let (mut bin_metadata, existing_cid) = match crate::api::ipns::resolve_ipns(&api, &bin_ipns_name).await {
833→+                Ok(resp) => {
834→+                    // Fetch and decrypt existing bin metadata
835→+                    match crate::api::ipfs::fetch_content(&api, &resp.cid).await {
836→+                        Ok(bytes) => {
837→+                            match crate::crypto::bin::decrypt_bin_metadata(&bytes, &user_private_key) {
838→+                                Ok(meta) => (meta, Some(resp.cid)),
839→+                                Err(e) => {
840→+                                    // Cannot decrypt existing bin — do NOT overwrite with empty.
841→+                                    // The CID stays pinned so no data is lost.
842→+                                    log::warn!("Failed to decrypt existing bin metadata, skipping publish to preserve existing data: {}", e);
843→+                                    return Err(format!("Bin decrypt failed, entry not published: {}", e));
844→+                                }
845→+                            }
846→+                        }
847→+                        Err(e) => {
848→+                            // Cannot fetch existing blob — do NOT overwrite with empty.
849→+                            log::warn!("Failed to fetch bin metadata blob, skipping publish to preserve existing data: {}", e);
850→+                            return Err(format!("Bin fetch failed, entry not published: {}", e));
851→+                        }
852→+                    }
853→+                }
854→+                Err(_) => {
855→+                    // No existing bin IPNS record -- first time using bin
856→+                    (crate::crypto::bin::empty_bin_metadata(), None)
857→+                }
858→+            };
859→+
860→+            // 4. Add the new entry and increment sequence number
861→+            bin_metadata.sequence_number += 1;
862→+            bin_metadata.entries.push(entry);
863→+
864→+            // 5. Encrypt with ECIES using user's public key
865→+            let encrypted = crate::crypto::bin::encrypt_bin_metadata(&bin_metadata, &user_public_key)
866→+                .map_err(|e| format!("Bin metadata encryption failed: {}", e))?;
867→+
868→+            // 6. Upload to IPFS
869→+            let new_cid = crate::api::ipfs::upload_content(&api, &encrypted).await?;
870→+
871→+            // 7. Resolve current IPNS sequence and publish
872→+            let seq = coordinator.resolve_sequence(&api, &bin_ipns_name).await.unwrap_or(0);
873→+            let new_seq = seq + 1;
874→+
875→+            let bin_ipns_key_arr: [u8; 32] = bin_ipns_private_key.as_slice().try_into()
876→+                .map_err(|_| "Invalid bin IPNS key length".to_string())?;
877→+            let value = format!("/ipfs/{}", new_cid);
878→+            let record = crate::crypto::ipns::create_ipns_record(
879→+                &bin_ipns_key_arr, &value, new_seq, 86_400_000,
880→+            ).map_err(|e| format!("Bin IPNS record creation failed: {}", e))?;
881→+            let marshaled = crate::crypto::ipns::marshal_ipns_record(&record)
882→+                .map_err(|e| format!("Bin IPNS marshal failed: {}", e))?;
883→+
884→+            use base64::Engine;
885→+            let record_b64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);
886→+
887→+            let req = crate::api::ipns::IpnsPublishRequest {
888→+                ipns_name: bin_ipns_name.clone(),
889→+                record: record_b64,
890→+                metadata_cid: new_cid,
891→+                encrypted_ipns_private_key: None,
892→+                key_epoch: None,
893→+                expected_sequence_number: Some(seq.to_string()),
894→+            };
895→+
896→+            match crate::api::ipns::publish_ipns(&api, &req).await? {
897→+                crate::api::ipns::PublishResult::Success => {
898→+                    coordinator.record_publish(&bin_ipns_name, new_seq);
899→+                    // Unpin old bin metadata CID
900→+                    if let Some(old) = existing_cid {
901→+                        let _ = crate::api::ipfs::unpin_content(&api, &old).await;
902→+                    }
903→+                    log::info!("Bin entry published for '{}'", bin_metadata.entries.last().map(|e| e.name.as_str()).unwrap_or("?"));
904→+                }
905→+                crate::api::ipns::PublishResult::Conflict { current_sequence_number } => {
906→+                    // On conflict, log warning. The entry will be lost for this delete,
907→+                    // but the CID stays pinned (no data loss). Next delete or web app
908→+                    // session will create a fresh bin state.
909→+                    log::warn!(
910→+                        "Bin IPNS publish conflict (expected {}, server {}). Bin entry not saved, but CID preserved.",
911→+                        seq, current_sequence_number
912→+                    );
913→+                }
914→+            }
915→+
916→+            Ok::<(), String>(())
917→+        });
918→+
919→+        if let Err(e) = result {
920→+            log::error!("Background bin entry publish failed: {}", e);
921→+        }
922→+    });
923→+}
