3133→+/**
3134→+ * Resolve the target folder for a restore operation.
3135→+ *
3136→+ * Walks the folder store to find a folder with the given IPNS name.
3137→+ * If not found, checks if the parent is in the bin (recursive restore).
3138→+ * Falls back to root folder.
3139→+ */
3140→+async function resolveTargetFolder(
3141→+  parentIpnsName: string,
3142→+  depth: number,
3143→+  params: { userPublicKey: Uint8Array; userPrivateKey: Uint8Array }
3144→+): Promise<FolderNode> {
3145→+  // Max recursion depth to prevent infinite loops
3146→+  if (depth > 5) {
3147→+    console.warn('[Bin] Max restore depth reached, falling back to root');
3148→+    return getRootFolder();
3149→+  }
3150→+
