306→fn spawn_metadata_publish(
307→    api: Arc<ApiClient>,
308→    rt: tokio::runtime::Handle,
309→    metadata: crate::crypto::folder::FolderMetadata,
310→    folder_key: Vec<u8>,
311→    ipns_private_key: Vec<u8>,
312→    ipns_name: String,
313→    old_metadata_cid: Option<String>,
314→    coordinator: Arc<PublishCoordinator>,
315→) {
316→    std::thread::spawn(move || {
317→        let result = rt.block_on(async {
318→            // Acquire per-folder publish lock to serialize concurrent publishes
319→            let lock = coordinator.get_lock(&ipns_name);
320→            let _guard = lock.lock().await;
321→
322→            // Encrypt metadata (CPU)
323→            let json_bytes = encrypt_metadata_to_json(&metadata, &folder_key)?;
324→
325→            // Resolve current IPNS sequence number (monotonic cache fallback)
326→            let seq = coordinator.resolve_sequence(&api, &ipns_name).await?;
327→
328→            // Upload encrypted metadata to IPFS
329→            let new_cid = crate::api::ipfs::upload_content(&api, &json_bytes).await?;
330→
331→            // Create and sign IPNS record
332→            let ipns_key_arr: [u8; 32] = ipns_private_key
333→                .try_into()
334→                .map_err(|_| "Invalid IPNS private key length".to_string())?;
335→            let new_seq = seq + 1;
336→            let value = format!("/ipfs/{}", new_cid);
337→            let record = crate::crypto::ipns::create_ipns_record(
338→                &ipns_key_arr,
339→                &value,
340→                new_seq,
341→                86_400_000,
342→            )
343→            .map_err(|e| format!("IPNS record creation failed: {}", e))?;
344→            let marshaled = crate::crypto::ipns::marshal_ipns_record(&record)
345→                .map_err(|e| format!("IPNS record marshal failed: {}", e))?;
346→
347→            use base64::Engine;
348→            let record_b64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);
349→
350→            let req = crate::api::ipns::IpnsPublishRequest {
351→                ipns_name: ipns_name.clone(),
352→                record: record_b64,
353→                metadata_cid: new_cid.clone(),
354→                encrypted_ipns_private_key: None,
355→                key_epoch: None,
356→                expected_sequence_number: Some(seq.to_string()),
357→            };
358→
359→            match crate::api::ipns::publish_ipns(&api, &req).await? {
360→                crate::api::ipns::PublishResult::Success => {
361→                    // Publish succeeded on first attempt
362→                    coordinator.record_publish(&ipns_name, new_seq);
363→
364→                    // Unpin old metadata CID
365→                    if let Some(old) = old_metadata_cid {
366→                        let _ = crate::api::ipfs::unpin_content(&api, &old).await;
367→                    }
368→
369→                    log::info!("Background metadata publish succeeded for {}", ipns_name);
370→                }
371→
372→                crate::api::ipns::PublishResult::Conflict { current_sequence_number } => {
373→                    // Another device published since our last sync.
374→                    // Re-fetch remote state, merge local changes, and retry once.
375→                    log::warn!(
376→                        "Conflict detected for {}: expected seq {}, server has {}. Re-syncing...",
377→                        ipns_name, seq, current_sequence_number
378→                    );
379→
380→                    // 1. Re-resolve the sequence number from the server (fresh, authoritative)
381→                    let fresh_seq = coordinator.resolve_sequence(&api, &ipns_name).await?;
382→
383→                    // 2. Resolve the IPNS name to get the remote CID
384→                    let remote_resolve = crate::api::ipns::resolve_ipns(&api, &ipns_name).await?;
385→                    let remote_cid = remote_resolve.cid;
386→
387→                    // 3. Fetch and decrypt the remote metadata (contains the other device's changes)
388→                    let remote_bytes = crate::api::ipfs::fetch_content(&api, &remote_cid).await?;
389→                    let remote_metadata = crate::fuse::decrypt::decrypt_metadata_from_ipfs_public(
390→                        &remote_bytes, &folder_key,
391→                    )?;
392→
393→                    // 4. Merge: apply local mutation onto remote children.
394→                    //    Preserves both this device's changes AND the other device's changes.
395→                    let merged_metadata = merge_folder_children(&metadata, remote_metadata);
396→
397→                    // 5. Small random jitter to break symmetry with other concurrent devices
398→                    let jitter_ms = (std::time::SystemTime::now()
399→                        .duration_since(std::time::UNIX_EPOCH)
400→                        .unwrap_or_default()
401→                        .subsec_nanos() % 400) as u64 + 100;
402→                    tokio::time::sleep(std::time::Duration::from_millis(jitter_ms)).await;
403→
404→                    // 6. Re-encrypt the MERGED metadata and upload
405→                    let retry_json = encrypt_metadata_to_json(&merged_metadata, &folder_key)?;
406→                    let retry_cid = crate::api::ipfs::upload_content(&api, &retry_json).await?;
407→
408→                    // 7. Create new IPNS record with fresh sequence
409→                    let retry_seq = fresh_seq + 1;
410→                    let retry_value = format!("/ipfs/{}", retry_cid);
411→                    let retry_record = crate::crypto::ipns::create_ipns_record(
412→                        &ipns_key_arr, &retry_value, retry_seq, 86_400_000,
413→                    ).map_err(|e| format!("IPNS retry record creation failed: {}", e))?;
414→                    let retry_marshaled = crate::crypto::ipns::marshal_ipns_record(&retry_record)
415→                        .map_err(|e| format!("IPNS retry record marshal failed: {}", e))?;
416→                    let retry_b64 = base64::engine::general_purpose::STANDARD.encode(&retry_marshaled);
417→
418→                    let retry_cid_for_cleanup = retry_cid.clone();
419→                    let retry_req = crate::api::ipns::IpnsPublishRequest {
420→                        ipns_name: ipns_name.clone(),
421→                        record: retry_b64,
422→                        metadata_cid: retry_cid,
423→                        encrypted_ipns_private_key: None,
424→                        key_epoch: None,
425→                        expected_sequence_number: Some(fresh_seq.to_string()),
426→                    };
427→
428→                    match crate::api::ipns::publish_ipns(&api, &retry_req).await? {
429→                        crate::api::ipns::PublishResult::Success => {
430→                            coordinator.record_publish(&ipns_name, retry_seq);
431→
432→                            // Unpin orphaned CID from first failed attempt
433→                            let _ = crate::api::ipfs::unpin_content(&api, &new_cid).await;
434→                            // Unpin old metadata CID (same as success path)
435→                            if let Some(old) = old_metadata_cid {
436→                                let _ = crate::api::ipfs::unpin_content(&api, &old).await;
437→                            }
438→
439→                            log::info!(
440→                                "Conflict resolved for {} after retry (seq {})",
441→                                ipns_name, retry_seq
442→                            );
443→                        }
444→                        crate::api::ipns::PublishResult::Conflict { .. } => {
445→                            // Persistent conflict after single retry -- do not loop.
446→                            // User should wait for automatic resync on next polling cycle.
447→                            // Best-effort cleanup of orphaned CIDs from both attempts.
448→                            let _ = crate::api::ipfs::unpin_content(&api, &new_cid).await;
449→                            let _ = crate::api::ipfs::unpin_content(&api, &retry_cid_for_cleanup).await;
450→
451→                            log::error!(
452→                                "Persistent conflict for {} after retry. \
453→                                Another device is actively modifying this folder. \
454→                                Changes will resync on next polling cycle.",
455→                                ipns_name
456→                            );
457→                            return Err(format!(
458→                                "Persistent conflict for {}. Another device is actively modifying this folder.",
459→                                ipns_name
460→                            ));
461→                        }
462→                    }
463→                }
464→            }
465→
466→            Ok::<(), String>(())
467→        });
468→
469→        if let Err(e) = result {
470→            log::error!("Background metadata publish failed: {}", e);
471→        }
472→    });
473→}
